import requests
import sys

if __name__ == '__main__':
    print('Package file: ')
    input_file = sys.stdin.readline().strip()
    output_lines = []

    with open(input_file, 'r') as file:
        for line in file:
            package = line.strip()
            if package:
                response = requests.get(f'https://pypi.org/pypi/{package}/json')
                if response.status_code == 200:
                    data = response.json()
                    version = data['info']['version']
                    output_line = f'{package}=={version}'
                    print(output_line)
                    output_lines.append(output_line)
                else:
                    print(f'{package}: unavailable')
                    output_lines.append(f'{package}: unavailable')

    with open('latest_versions.txt', 'w') as output_file:
        for line in output_lines:
            output_file.write(line + '\n')
